def f(x):
    return sin(x)
def pi():
    while True:
        n=int(input("Donner N: "))
        if 10 <= n <= 100:
            break
    a = int(input("Choisir a: "))
    b = int(input("Choisir b: "))
    T = [{}]*n
    e = {}
    x = int(input("Choisir la valeur initiative de x: "))
    s = f(x)
    p = abs(a-b)/n
    for i in range(n):
        e = {}
        e["ab"] = x
        e["img"] = f(x)
        T[i] = e
        x += p
        if abs(s) > abs(T[i]["img"]):
            s = T[i]["img"]
            k = T[i]["ab"]
    for i in range(n):
        print("L'abscisse est: ",T[i]["ab"],"Son image est: ",T[i]["img"])
    print("La valeur approché de pi est: ",k)
pi()

